-- Relation row types as composite attributes and PL/pgSQL row fields, and the
-- drops that cascade to their users.
CREATE TABLE orders (id int, total numeric);
INSERT INTO orders VALUES (1, 9.5);
CREATE TYPE wrap AS (o orders, n int);
SELECT ROW(o, 1)::wrap FROM orders o;
SELECT (ROW(o, 1)::wrap).o.total FROM orders o;
CREATE TABLE holder (w wrap);
INSERT INTO holder SELECT ROW(o, 2)::wrap FROM orders o;
SELECT * FROM holder;
SELECT pg_describe_object(classid, objid, objsubid), pg_describe_object(refclassid, refobjid, refobjsubid), deptype FROM pg_depend WHERE refobjid = 'orders'::regtype ORDER BY 1;
CREATE VIEW vo AS SELECT id FROM orders;
CREATE TYPE wrapv AS (v vo);
CREATE MATERIALIZED VIEW mo AS SELECT id FROM orders;
CREATE TYPE wrapm AS (m mo);
ALTER TABLE orders ADD COLUMN extra int;
ALTER TABLE orders ALTER COLUMN total TYPE float8;
DROP TABLE orders;
DROP TYPE wrap;
DROP TABLE orders CASCADE;
\d holder
DROP TABLE holder;
DROP TYPE wrap;
DROP VIEW vo CASCADE;
DROP MATERIALIZED VIEW mo CASCADE;
CREATE TABLE ord2 (id int);
CREATE FUNCTION f() RETURNS int LANGUAGE plpgsql AS $$ DECLARE r ord2; BEGIN r.id := 5; RETURN r.id; END $$;
SELECT f();
CREATE FUNCTION f2() RETURNS text LANGUAGE plpgsql AS $$ DECLARE r ord2; BEGIN SELECT * INTO r FROM ord2; RETURN r::text; END $$;
INSERT INTO ord2 VALUES (7);
SELECT f2();
CREATE FUNCTION f3() RETURNS text LANGUAGE plpgsql AS $$ DECLARE r ord2%ROWTYPE; BEGIN SELECT * INTO r FROM ord2; RETURN r::text; END $$;
SELECT f3();
DROP TABLE ord2 CASCADE;
DROP FUNCTION f(); DROP FUNCTION f2(); DROP FUNCTION f3();
CREATE SCHEMA s;
CREATE TABLE s.t (a int);
CREATE TABLE h (c s.t, n int);
CREATE DOMAIN dt AS s.t;
CREATE TYPE w AS (x s.t, y int);
INSERT INTO h VALUES (ROW(1), 2);
DROP SCHEMA s;
DROP SCHEMA s CASCADE;
SELECT * FROM h;
SELECT typname FROM pg_type WHERE typname = 'dt';
SELECT attname FROM pg_attribute WHERE attrelid = 'w'::regclass AND attnum > 0 ORDER BY attnum;
DROP TYPE w;
DROP TABLE h;
CREATE TABLE base (a int, b text);
CREATE MATERIALIZED VIEW mvb AS SELECT a FROM base;
CREATE TABLE hm (m mvb);
CREATE TYPE wm AS (m mvb, k int);
DROP MATERIALIZED VIEW mvb;
DROP MATERIALIZED VIEW mvb CASCADE;
\d hm
SELECT attname FROM pg_attribute WHERE attrelid = 'wm'::regclass AND attnum > 0 AND NOT attisdropped ORDER BY attnum;
DROP TABLE hm;
DROP TYPE wm;
CREATE VIEW vb AS SELECT a FROM base;
CREATE TABLE hv (v vb);
CREATE FUNCTION fb() RETURNS int LANGUAGE sql BEGIN ATOMIC SELECT a FROM vb; END;
DROP TABLE base CASCADE;
\d hv
DROP TABLE hv;
CREATE FOREIGN DATA WRAPPER fw;
CREATE SERVER fs FOREIGN DATA WRAPPER fw;
CREATE FOREIGN TABLE ft (a int) SERVER fs;
CREATE TABLE hf (f ft, z int);
DROP FOREIGN TABLE ft;
DROP FOREIGN TABLE ft CASCADE;
\d hf
DROP TABLE hf;
DROP SERVER fs;
DROP FOREIGN DATA WRAPPER fw;
CREATE TABLE t (a int);
CREATE DOMAIN dt AS t;
DROP TABLE t CASCADE;
CREATE SCHEMA s;
CREATE TABLE s.t (a int);
CREATE DOMAIN dt AS s.t;
DROP SCHEMA s CASCADE;
CREATE SCHEMA s;
CREATE TABLE s.t (a int);
CREATE DOMAIN s.dt AS s.t;
DROP SCHEMA s CASCADE;
DROP DOMAIN dt;CREATE TABLE ord2 (id int, v text);
CREATE TYPE pair AS (id int, v text);
CREATE FUNCTION f() RETURNS int LANGUAGE plpgsql AS $$ DECLARE r ord2; BEGIN r.id := 5; RETURN r.id; END $$;
SELECT f();
CREATE FUNCTION fc() RETURNS int LANGUAGE plpgsql AS $$ DECLARE r pair; BEGIN r.id := 5; RETURN r.id; END $$;
SELECT fc();
CREATE FUNCTION fr() RETURNS text LANGUAGE plpgsql AS $$ DECLARE r ord2%ROWTYPE; BEGIN r.v := 'a'; RETURN r::text; END $$;
SELECT fr();
CREATE FUNCTION fx() RETURNS text LANGUAGE plpgsql AS $$ DECLARE r ord2; BEGIN r := ROW(1, 'b'); RETURN r.v; END $$;
SELECT fx();
CREATE FUNCTION fy() RETURNS text LANGUAGE plpgsql AS $$ DECLARE r ord2 := ROW(2, 'c'); BEGIN RETURN r.v || r.id; END $$;
SELECT fy();
CREATE TABLE ord3 (id int, v text);
CREATE FUNCTION g1() RETURNS text LANGUAGE plpgsql AS $$ DECLARE r ord3; BEGIN r.nope := 5; RETURN r::text; END $$;
SELECT g1();
CREATE FUNCTION g2() RETURNS text LANGUAGE plpgsql AS $$ DECLARE r record; BEGIN r.id := 5; RETURN r::text; END $$;
SELECT g2();
CREATE FUNCTION g3() RETURNS text LANGUAGE plpgsql AS $$ DECLARE r record; BEGIN SELECT 1 AS id, 'x' AS v INTO r; r.id := 7; r.v := 42; RETURN r::text || r.v; END $$;
SELECT g3();
CREATE FUNCTION g4() RETURNS text LANGUAGE plpgsql AS $$ DECLARE r ord3; BEGIN r.id := 'abc'; RETURN r::text; END $$;
SELECT g4();
CREATE FUNCTION g5() RETURNS text LANGUAGE plpgsql AS $$ DECLARE r ord3; BEGIN SELECT * INTO r FROM (VALUES (1, 'q')) s; r.v := r.v || '!'; RETURN r::text; END $$;
SELECT g5();
DROP TABLE ord3 CASCADE;
DROP FUNCTION g1(), g2(), g3(), g4(), g5();
DROP TABLE ord2 CASCADE;
DROP TYPE pair;
DROP FUNCTION f(), fc(), fr(), fx(), fy();
CREATE TABLE o5 (id int);
CREATE TYPE w5 AS (k int);
ALTER TYPE w5 ADD ATTRIBUTE o o5;
ALTER TYPE w5 ADD ATTRIBUTE os o5[];
SELECT pg_describe_object(classid, objid, objsubid), pg_describe_object(refclassid, refobjid, refobjsubid), deptype FROM pg_depend WHERE refobjid IN ('o5'::regtype, 'o5[]'::regtype) ORDER BY 1, 2;
DROP TABLE o5 CASCADE;
SELECT attname FROM pg_attribute WHERE attrelid = 'w5'::regclass AND attnum > 0 AND NOT attisdropped;
DROP TYPE w5;
